package routes

import (
	"github.com/goravel/framework/contracts/route"
	"github.com/macrowallets/waas/app/container"
	"github.com/macrowallets/waas/app/facades"
	ctrl "github.com/macrowallets/waas/app/http/controllers/ramps"
	"github.com/macrowallets/waas/app/http/middleware"
	accountsvc "github.com/macrowallets/waas/app/services/account"
	"github.com/macrowallets/waas/app/services/features"
	"github.com/macrowallets/waas/app/services/ramps"
	"github.com/macrowallets/waas/app/services/settings"
	"github.com/macrowallets/waas/app/services/walletrecords"
)

func RegisterRamps() {
	service := container.MustMake[*ramps.Service]()
	accounts := container.MustMake[*accountsvc.Service]()
	operations := ctrl.NewOperationsController(service)
	funding := ctrl.NewFundingController(service)
	flow := ctrl.NewFlowHandler(service)
	customers := ctrl.NewCustomersController(service)
	facades.Route().Prefix("/v1").Middleware(middleware.SessionAuth(), middleware.AccountHeader(accounts), middleware.TOTPEnrollment(container.MustMake[*features.Service](), container.MustMake[*settings.Service]()), middleware.CacheControl(0)).Group(func(r route.Router) {
		r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersRead)).Get("/customers", customers.Index)
		r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersWrite)).Post("/customers", customers.Store)
		r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersRead)).Get("/account-holder", customers.AccountHolder)
		r.Prefix("/customers/{customerId}").Middleware(middleware.RampCustomerContext(service)).Group(func(r route.Router) {
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersRead)).Get("", customers.Show)
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceRead)).Get("/operations", operations.Index)
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersCreate)).Post("/operations/{id}/resolve", operations.Resolve)
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersWrite)).Patch("/features/{feature}", customers.SetFeature)
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersRead)).Get("/features", customers.Features)
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersRead)).Get("/wallets", customers.Wallets)
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampProfileRead)).Get("/bank-accounts", flow.Action("bank_accounts.Index"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersWrite)).Post("/bank-accounts", flow.Action("bank_accounts.Store"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampProfileRead)).Get("/beneficiaries", flow.Action("beneficiaries.Index"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersWrite)).Post("/beneficiaries", flow.Action("beneficiaries.Store"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceRead)).Get("/integrations", flow.Action("integrations.Index"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceRead)).Get("/kyc", flow.Action("kyc.Index"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/application", flow.Action("kyc.SubmitApplicationFanOut"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceRead)).Get("/kyc/capabilities", flow.Action("kyc.Capabilities"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceRead)).Get("/kyc/countries", flow.Action("kyc.Countries"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/documents", flow.Action("kyc.SubmitDocumentsFanOut"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceRead)).Get("/kyc/overview", flow.Action("kyc.Overview"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceWrite)).Post("/kyc/overview/refresh", flow.Action("kyc.RefreshOverview"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampProfileRead), middleware.RampProfileAudit(service)).Get("/kyc/profile", flow.Action("kyc.Profile"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampProfileRead), middleware.RampProfileAudit(service)).Get("/kyc/business-profile", customers.BusinessProfile)
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/tos", flow.Action("kyc.StartTosFanOut"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/tos/acceptances", flow.Action("kyc.RecordTosAcceptances"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersRead)).Get("/offramps", flow.Action("offramps.Index"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersCreate), middleware.RampNewOperations(service)).Post("/offramps", flow.Action("offramps.Create"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersRead)).Get("/offramps/bank-options", flow.Action("offramps.BankOptions"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersCreate), middleware.RampNewOperations(service)).Post("/offramps/estimate", flow.Action("offramps.Estimate"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersRead)).Get("/onramps", flow.Action("onramps.Index"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersCreate), middleware.RampNewOperations(service)).Post("/onramps", flow.Action("onramps.Create"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersCreate), middleware.RampNewOperations(service)).Post("/onramps/estimate", flow.Action("onramps.Estimate"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersCreate), middleware.RampNewOperations(service)).Post("/payout-addresses", flow.Action("payout_addresses.Provision"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampProfileRead)).Get("/pix-keys", flow.Action("pix_keys.Index"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersWrite)).Post("/pix-keys", flow.Action("pix_keys.Store"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersCreate), middleware.RampNewOperations(service)).Post("/virtual-accounts", flow.Action("virtual_accounts.Provision"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersRead)).Get("/virtual-accounts", flow.Action("virtual_accounts.Show"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersCreate)).Patch("/virtual-accounts", flow.Action("virtual_accounts.UpdateDestination"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersWrite), middleware.RampNewOperations(service)).Post("/wallets", flow.Action("wallets.Store"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersWrite)).Patch("/bank-accounts/{id}", flow.Action("bank_accounts.Update"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersWrite)).Delete("/bank-accounts/{id}", flow.Action("bank_accounts.Destroy"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampProfileRead)).Get("/beneficiaries/{id}", flow.Action("beneficiaries.Show"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersWrite)).Patch("/beneficiaries/{id}", flow.Action("beneficiaries.Update"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersWrite)).Delete("/beneficiaries/{id}", flow.Action("beneficiaries.Destroy"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceRead)).Get("/integrations/{provider}", flow.Action("integrations.Show"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/integrations/{provider}", flow.Action("integrations.Start"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceWrite)).Post("/integrations/{provider}/refresh", flow.Action("integrations.Refresh"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceRead)).Get("/kyc/{provider}", flow.Action("kyc.Show"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/{provider}/application", flow.Action("kyc.SubmitApplication"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/{provider}/documents", flow.Action("kyc.SubmitDocuments"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/{provider}/endorsements", flow.Action("kyc.RequestEndorsements"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/{provider}/hosted-link", flow.Action("kyc.HostedLink"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceWrite)).Post("/kyc/{provider}/refresh", flow.Action("kyc.Refresh"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceRead)).Get("/kyc/{provider}/requirements", flow.Action("kyc.Requirements"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/{provider}/tos", flow.Action("kyc.StartTos"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersRead)).Get("/offramps/{id}", flow.Action("offramps.Show"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersCreate)).Post("/offramps/{id}/cancel", flow.Action("offramps.Cancel"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersCreate)).Post("/offramps/{id}/finalize", flow.Action("offramps.Finalize"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersCreate), middleware.RequireFundAction(middleware.FundWithdraw), middleware.WalletContext(middleware.WalletContextDeps{Wallets: container.MustMake[*walletrecords.Wallets](), Accounts: accounts, Members: container.MustMake[*walletrecords.Members]()})).Post("/offramps/{id}/wallets/{walletId}/fund", funding.Fund)
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersCreate)).Post("/offramps/{id}/funding-action", flow.Action("offramps.RefreshFundingAction"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersCreate)).Post("/offramps/{id}/simulate-deposit", flow.Action("offramps.SimulateDeposit"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersRead)).Get("/onramps/{id}", flow.Action("onramps.Show"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampOrdersCreate)).Post("/payout-addresses/{id}/simulate-deposit", flow.Action("payout_addresses.SimulateDeposit"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersWrite)).Patch("/pix-keys/{id}", flow.Action("pix_keys.Update"))
			r.Middleware(middleware.RampSessionPermission(middleware.PermRampCustomersWrite)).Delete("/pix-keys/{id}", flow.Action("pix_keys.Destroy"))
		})
	})
	facades.Route().Prefix("/api/v1").Middleware(middleware.Throttle(middleware.ThrottleAPI), middleware.APITokenAuth(accounts), middleware.CacheControl(0)).Group(func(r route.Router) {
		r.Middleware(middleware.RampTokenPermission(middleware.PermRampCustomersRead)).Get("/customers", customers.Index)
		r.Middleware(middleware.RampTokenPermission(middleware.PermRampCustomersWrite)).Post("/customers", customers.Store)
		r.Middleware(middleware.RampTokenPermission(middleware.PermRampCustomersRead)).Get("/account-holder", customers.AccountHolder)
		r.Prefix("/customers/{customerId}").Middleware(middleware.RampCustomerContext(service)).Group(func(r route.Router) {
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampCustomersRead)).Get("", customers.Show)
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampCustomersRead)).Get("/features", customers.Features)
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampCustomersRead)).Get("/wallets", customers.Wallets)
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampProfileRead)).Get("/bank-accounts", flow.Action("bank_accounts.Index"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampCustomersWrite)).Post("/bank-accounts", flow.Action("bank_accounts.Store"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampProfileRead)).Get("/beneficiaries", flow.Action("beneficiaries.Index"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampCustomersWrite)).Post("/beneficiaries", flow.Action("beneficiaries.Store"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceRead)).Get("/integrations", flow.Action("integrations.Index"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceRead)).Get("/kyc", flow.Action("kyc.Index"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/application", flow.Action("kyc.SubmitApplicationFanOut"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceRead)).Get("/kyc/capabilities", flow.Action("kyc.Capabilities"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceRead)).Get("/kyc/countries", flow.Action("kyc.Countries"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/documents", flow.Action("kyc.SubmitDocumentsFanOut"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceRead)).Get("/kyc/overview", flow.Action("kyc.Overview"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceWrite)).Post("/kyc/overview/refresh", flow.Action("kyc.RefreshOverview"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampProfileRead), middleware.RampProfileAudit(service)).Get("/kyc/profile", flow.Action("kyc.Profile"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampProfileRead), middleware.RampProfileAudit(service)).Get("/kyc/business-profile", customers.BusinessProfile)
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/tos", flow.Action("kyc.StartTosFanOut"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/tos/acceptances", flow.Action("kyc.RecordTosAcceptances"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersRead)).Get("/offramps", flow.Action("offramps.Index"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersCreate), middleware.RampNewOperations(service)).Post("/offramps", flow.Action("offramps.Create"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersRead)).Get("/offramps/bank-options", flow.Action("offramps.BankOptions"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersCreate), middleware.RampNewOperations(service)).Post("/offramps/estimate", flow.Action("offramps.Estimate"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersRead)).Get("/onramps", flow.Action("onramps.Index"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersCreate), middleware.RampNewOperations(service)).Post("/onramps", flow.Action("onramps.Create"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersCreate), middleware.RampNewOperations(service)).Post("/onramps/estimate", flow.Action("onramps.Estimate"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersCreate), middleware.RampNewOperations(service)).Post("/payout-addresses", flow.Action("payout_addresses.Provision"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampProfileRead)).Get("/pix-keys", flow.Action("pix_keys.Index"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampCustomersWrite)).Post("/pix-keys", flow.Action("pix_keys.Store"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersCreate), middleware.RampNewOperations(service)).Post("/virtual-accounts", flow.Action("virtual_accounts.Provision"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersRead)).Get("/virtual-accounts", flow.Action("virtual_accounts.Show"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersCreate)).Patch("/virtual-accounts", flow.Action("virtual_accounts.UpdateDestination"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampCustomersWrite), middleware.RampNewOperations(service)).Post("/wallets", flow.Action("wallets.Store"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampCustomersWrite)).Patch("/bank-accounts/{id}", flow.Action("bank_accounts.Update"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampCustomersWrite)).Delete("/bank-accounts/{id}", flow.Action("bank_accounts.Destroy"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampProfileRead)).Get("/beneficiaries/{id}", flow.Action("beneficiaries.Show"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampCustomersWrite)).Patch("/beneficiaries/{id}", flow.Action("beneficiaries.Update"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampCustomersWrite)).Delete("/beneficiaries/{id}", flow.Action("beneficiaries.Destroy"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceRead)).Get("/integrations/{provider}", flow.Action("integrations.Show"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/integrations/{provider}", flow.Action("integrations.Start"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceWrite)).Post("/integrations/{provider}/refresh", flow.Action("integrations.Refresh"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceRead)).Get("/kyc/{provider}", flow.Action("kyc.Show"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/{provider}/application", flow.Action("kyc.SubmitApplication"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/{provider}/documents", flow.Action("kyc.SubmitDocuments"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/{provider}/endorsements", flow.Action("kyc.RequestEndorsements"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/{provider}/hosted-link", flow.Action("kyc.HostedLink"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceWrite)).Post("/kyc/{provider}/refresh", flow.Action("kyc.Refresh"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceRead)).Get("/kyc/{provider}/requirements", flow.Action("kyc.Requirements"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampComplianceWrite), middleware.RampNewOperations(service)).Post("/kyc/{provider}/tos", flow.Action("kyc.StartTos"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersRead)).Get("/offramps/{id}", flow.Action("offramps.Show"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersCreate)).Post("/offramps/{id}/cancel", flow.Action("offramps.Cancel"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersCreate)).Post("/offramps/{id}/finalize", flow.Action("offramps.Finalize"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersCreate)).Post("/offramps/{id}/funding-action", flow.Action("offramps.RefreshFundingAction"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersCreate)).Post("/offramps/{id}/simulate-deposit", flow.Action("offramps.SimulateDeposit"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersRead)).Get("/onramps/{id}", flow.Action("onramps.Show"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampOrdersCreate)).Post("/payout-addresses/{id}/simulate-deposit", flow.Action("payout_addresses.SimulateDeposit"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampCustomersWrite)).Patch("/pix-keys/{id}", flow.Action("pix_keys.Update"))
			r.Middleware(middleware.RampTokenPermission(middleware.PermRampCustomersWrite)).Delete("/pix-keys/{id}", flow.Action("pix_keys.Destroy"))
		})
	})
}
